#include "placer/database/PlacementDB.hpp"
#include <algorithm>
#include <stdexcept>
namespace placer { CellId PlacementDB::addCell(const std::string& n,double w,double h,bool t){ if(cell_name_to_id.count(n)) throw std::runtime_error("duplicate cell: "+n); CellId id=cells.size(); cell_name_to_id[n]=id; cells.push_back({n,w,h,0,0,t,t,"N"}); return id;} NetId PlacementDB::addNet(const std::string& n){NetId id=nets.size(); nets.push_back({n,{}}); return id;} PinId PlacementDB::addPin(CellId c,NetId n,double ox,double oy,const std::string& d){PinId id=pins.size(); pins.push_back({c,n,ox,oy,d}); nets[n].pin_ids.push_back(id); return id;} Region PlacementDB::region()const{ if(!rows.empty()){double xl=rows[0].x_start,xh=rows[0].x_end,yl=rows[0].y,yh=rows[0].y+rows[0].height; for(auto&r:rows){xl=std::min(xl,r.x_start);xh=std::max(xh,r.x_end);yl=std::min(yl,r.y);yh=std::max(yh,r.y+r.height);} if(xh>xl&&yh>yl)return{xl,xh,yl,yh};} if(cells.empty())return{}; double xl=cells[0].x,xh=cells[0].x+cells[0].width,yl=cells[0].y,yh=cells[0].y+cells[0].height; for(auto&c:cells){xl=std::min(xl,c.x);xh=std::max(xh,c.x+c.width);yl=std::min(yl,c.y);yh=std::max(yh,c.y+c.height);} return{xl,std::max(xh,xl+1.0),yl,std::max(yh,yl+1.0)};} }
